    IERC20 public immutable rewardToken2 = IERC20(0x3E79130ab714E97ee73f86a56a2427bb1A519896); // Second reward token
    IMasterChef public masterchef1 = IMasterChef(0x486fEa20eA242456b450B005ED7D019E3E984f28); // First MasterChef contract
    IMasterChef public masterchef2 = IMasterChef(0xC84FbE083713544BB4Ea85E2fe95148D076b2942); // Second MasterChef contract
    uint256 public poolID1 = 24; // Pool ID for MasterChef 1
    uint256 public poolID2 = 28; // Pool ID for MasterChef 2

    mapping(address => UserInfo) public userInfo; // User data
    mapping(address => UserSettings) public userSettings; // User data
    mapping(address => uint256) public userCredit1; // User data
    mapping(address => uint256) public userCredit2; // User data
    uint256 public accDtxPerShareToken1; // Accumulated rewards per NFT for token 1
    uint256 public accDtxPerShareToken2; // Accumulated rewards per NFT for token 2
    uint256 public lastCredit1; // Last credit from MasterChef 1
    uint256 public lastCredit2; // Last credit from MasterChef 2
    uint256 public totalNFTs; // Total NFTs in circulation
    address public treasury = 0xD540b89Ee52F81bE921Aa856bb2808A96BA9E3a1; // Governing contract

    mapping(address => PoolPayout) public poolPayout; //determines the percentage received depending on withdrawal option
    mapping(address => PoolPayout) public poolPayout2; //for degen
    uint256 public defaultDirectPayout = 50; //0.5% if withdrawn into wallet

    //default harvest settings
    address public defaultHarvest = 0xf3E82f4123d4262a2baEC25b03652f3932A91739; //5year oink
    address public defaultHarvest2 = 0xdE672FccA32365bD704c39bd1164a0D34a3a73e6; //10year degen
    uint256 public defaultMinHarvestOink = 10000;
    uint256 public defaultMinHarvestDegen = 10000000000;
    uint256 public defaultFee = 100; //1%

    address public helperToken = 0xe1cAF2F0da06A97A7f04B9Ea1B43C91F447cf343;


    event Harvest(address indexed user, uint256 amountToken1, uint256 amountToken2);
    event NFTMinted(address indexed user, uint256 amount);
    event NFTBurned(address indexed user, uint256 amount);


    constructor() ERC1155("https://raw.githubusercontent.com/DegenStrategy/DEGEN/refs/heads/main/nftMinerMetadata.json") {
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].amount = 100;
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].minServe = 864000;

        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].amount = 300;
        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].minServe = 2592000;

        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].amount = 500;
        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].minServe = 5184000;

        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].amount = 1000;
        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].minServe = 8640000;

        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].amount = 2500;
        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].minServe = 20736000;

        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].amount = 10000;
        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].minServe = 31536000; 

        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].amount = 100;
        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].minServe = 864000;

        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].amount = 250;
