        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].amount = 500;
        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].minServe = 8640000;

        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].amount = 10000;
        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].minServe = 31536000; 
    }

    // Modifier for decentralized voting
    modifier decentralizedVoting() {
        require(msg.sender == masterchef2.owner(), "Decentralized Voting Only!");
        _;
    }


    // Mint new NFT
    function mint(address _to, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _mint(_to, MINING_UNIT, _amount, "");
        totalNFTs += _amount;
        userInfo[_to].nftCount += _amount;
        emit NFTMinted(_to, _amount);
    }

    // Burn mining units
    // harvest rewards before burning or you lose them
    function burn(address _user, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(balanceOf(_user, MINING_UNIT) >= _amount, "Insufficient balance");
        _burn(_user, MINING_UNIT, _amount);
        totalNFTs -= _amount;
        userInfo[_user].nftCount -= _amount;
        emit NFTBurned(_user, _amount);
    }

    function massHarvest(address[] calldata _users) external {
        for(uint256 i = 0; i< _users.length; ++i) {
            publicHarvest(_users[i]);
        }
    }

    // Harvest rewards for a user
    function publicHarvest(address _user) public  {
        _updatePool();
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        if (nftCount == 0) {
            return;
        }

        UserSettings storage userData = userSettings[_user];
        address _harvestInto = userData.defaultHarvest1;
        address _harvestInto2 = userData.defaultHarvest2;
        uint256 _minimumHarvest1 = userData.minimumHarvest1;
        uint256 _minimumHarvest2 = userData.minimumHarvest2;
        uint256 _fee = userData.fee;

        // use default settings if not set
        if(_harvestInto == address(0)) { _harvestInto = defaultHarvest; }
        if(_harvestInto2 == address(0)) { _harvestInto2 = defaultHarvest2; }
        if(_minimumHarvest1 == 0) { _minimumHarvest1 = defaultMinHarvestOink; }
        if(_minimumHarvest2 == 0) { _minimumHarvest2 = defaultMinHarvestDegen; }
        if(_fee == 1) { _fee = 0; } else if(_fee == 0) { _fee = defaultFee; } // user must set to 1 for 0 fee


        // Calculate pending rewards for both tokens
        uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];

        require(pendingToken1 >= _minimumHarvest1 && pendingToken2 >= _minimumHarvest2, "pending balance below minimum required threshold for harvest");

        // Update user's debt
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;

        uint256 _payout = 0;
        uint256 _penalty = 0;
        uint256 _harvestFee = 0;

        // Transfer rewards
        if (pendingToken1 > 0) {

            if(_harvestInto == msg.sender) {
                _payout = pendingToken1 * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(_user, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = pendingToken1 * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout[_harvestInto].minServe);
            }

            _penalty = pendingToken1 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit1 -= pendingToken1;
        }
        if (pendingToken2 > 0) {
            if(_harvestInto2 == msg.sender) {
                _payout = pendingToken2 * defaultDirectPayout / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(_user, (_payout-_harvestFee)); 
		    } else {
                require(poolPayout2[_harvestInto2].amount != 0, "incorrect pool!");
                _payout = pendingToken2 * poolPayout2[_harvestInto2].amount / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), (_payout-_harvestFee));
                IacPool(_harvestInto2).giftDeposit((_payout-_harvestFee), msg.sender, poolPayout2[_harvestInto2].minServe);
            }

            if(_harvestFee > 0) {
                IMasterChef(masterchef2).transferCredit(helperToken, _harvestFee);
		        IHelperToken(helperToken).mint(msg.sender, _harvestFee);
            }
            _penalty = pendingToken2 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit2 -= pendingToken2;
        }

        emit Harvest(_user, pendingToken1, pendingToken2);
    }

    //choose how much (the remaining gets left)
    function selfHarvest(uint256 _amount, address _harvestInto, bool _token1) external {
        _updatePool();
        UserInfo storage user = userInfo[msg.sender];
        uint256 nftCount = user.nftCount;

        require(nftCount > 0 || userCredit1[msg.sender] > 0 || userCredit2[msg.sender] > 0, "nothing to harvest!");

        uint256 _payout;
        uint256 _penalty;

        if(_token1) {
            uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[msg.sender];
            user.debtToken1 = accDtxPerShareToken1;
            user.lastAction = block.timestamp;
            if(pendingToken1 < _amount) { _amount = pendingToken1; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit1[msg.sender] = pendingToken1 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit1 -= _amount;
            emit Harvest(msg.sender, _amount, 0);
        } else { // token2 (degen)
            uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[msg.sender];
            user.debtToken2 = accDtxPerShareToken2;
            user.lastAction = block.timestamp;
            if(pendingToken2 < _amount) { _amount = pendingToken2; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit2[msg.sender] = pendingToken2 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef2).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout2[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout2[_harvestInto].amount / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout2[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit2 -= _amount;
            emit Harvest(msg.sender, 0, _amount);
        }
    }

    // Update pool rewards for both MasterChefs
    function _updatePool() internal {
        // Update MasterChef 1
        masterchef1.updatePool(poolID1);
        uint256 currentCredit1 = masterchef1.credit(address(this));
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;
        lastCredit1 = currentCredit1;


        // Update MasterChef 2
        masterchef2.updatePool(poolID2);
        uint256 currentCredit2 = masterchef2.credit(address(this));
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;
        lastCredit2 = currentCredit2;
        if (totalNFTs > 0) {
            accDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            accDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }
    }

    // Hook called before any NFT transfer
        function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal virtual override {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);

        if (from == address(0) || to == address(0)) {
            return; // Minting or burning, no need to update rewards
        }

        _updatePool();

        // Ensure single token ID (MINING_UNIT) is being transferred
        require(ids.length == 1 && ids[0] == MINING_UNIT, "Only MINING_UNIT transfers allowed");
        uint256 amount = amounts[0];

        // Harvest for sender
        if (from != address(0)) {
            UserInfo storage fromUser = userInfo[from];
            uint256 nftCount = fromUser.nftCount;
            if (nftCount > 0) {
                uint256 pendingToken1 = nftCount * (accDtxPerShareToken1 - fromUser.debtToken1) / 1e12;
                uint256 pendingToken2 = nftCount * (accDtxPerShareToken2 - fromUser.debtToken2) / 1e12;

                fromUser.debtToken1 = accDtxPerShareToken1;
                fromUser.debtToken2 = accDtxPerShareToken2;
                fromUser.lastAction = block.timestamp;

                if (pendingToken1 > 0) {
                    userCredit1[from] += pendingToken1;
                    lastCredit1 -= pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[from] += pendingToken2;
                    lastCredit2 -= pendingToken2;
                }
            }
            fromUser.nftCount -= amount;
        }

        // Update recipient's info
        if (to != address(0)) {
            UserInfo storage toUser = userInfo[to];
            if (toUser.nftCount > 0) {
                uint256 pendingToken1 = toUser.nftCount * (accDtxPerShareToken1 - toUser.debtToken1) / 1e12;
                uint256 pendingToken2 = toUser.nftCount * (accDtxPerShareToken2 - toUser.debtToken2) / 1e12;

                if (pendingToken1 > 0) {
                    userCredit1[to] += pendingToken1;
                    lastCredit1 -= pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[to] += pendingToken2;
                    lastCredit2 -= pendingToken2;
                }
            }
            toUser.nftCount += amount;
            toUser.debtToken1 = accDtxPerShareToken1;
            toUser.debtToken2 = accDtxPerShareToken2;
            toUser.lastAction = block.timestamp;
        }
    }

    // View function to check pending rewards for a user
    function viewUserTotalEarnings(address _user) external view returns (uint256 pendingToken1, uint256 pendingToken2) {
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        uint256 virtualAccDtxPerShareToken1 = accDtxPerShareToken1;
        uint256 virtualAccDtxPerShareToken2 = accDtxPerShareToken2;

        if (totalNFTs > 0) {
            uint256 pending1 = masterchef1.pendingDtx(poolID1);
            virtualAccDtxPerShareToken1 += pending1 * 1e12 / totalNFTs;

            uint256 pending2 = masterchef2.pendingDtx(poolID2);
            virtualAccDtxPerShareToken2 += pending2 * 1e12 / totalNFTs;
        }

        pendingToken1 = (nftCount * (virtualAccDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        pendingToken2 = (nftCount * (virtualAccDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];
    }

    // Update MasterChef addresses
    function setMasterChefAddresses(IMasterChef _masterchef1, IMasterChef _masterchef2, uint256 _poolID1, uint256 _poolID2) external decentralizedVoting {
        masterchef1 = _masterchef1;
        masterchef2 = _masterchef2;
        poolID1 = _poolID1;
        poolID2 = _poolID2;
    }

    // Update treasury address
    function updateTreasury(address _treasury) external decentralizedVoting {
        treasury = _treasury;
    }

    function setUserSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external {
        UserSettings storage userData = userSettings[msg.sender];
        require(_fee <= 2500, "Fee must be less than or equal to 25%");
        userData.fee = _fee;
        userData.defaultHarvest1 = _defaultharvest;
        userData.defaultHarvest2 = _defaultHarvest2;
        userData.minimumHarvest1 = _defaultMinHarvestOink;
        userData.minimumHarvest2 = _defaultminHarvestDegen;
    }

    function setDefaultSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external decentralizedVoting {
        require(_fee <= 500, "Fee must be less than or equal to 5%");
        defaultFee = _fee;
        defaultHarvest = _defaultharvest;
        defaultHarvest2 = _defaultHarvest2;
        defaultMinHarvestOink = _defaultMinHarvestOink;
        defaultMinHarvestDegen = _defaultminHarvestDegen;
    }

    function setPoolPayout(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout[_pool].amount = _amount;
        poolPayout[_pool].minServe = _minServe;
    }
    function setPoolPayout2(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout2[_pool].amount = _amount;
        poolPayout2[_pool].minServe = _minServe;
    }
    function setMintContract(address _a) external decentralizedVoting {
        mintContract = _a;
    }
}

