interface IHelperToken {
	function mint(address to, uint256 amount) external;
}

contract NFTVault is ERC1155, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MINING_UNIT = 1; // Single token ID for all identical mining units


    struct UserInfo {
        uint256 nftCount; // Number of NFTs owned by the user
        uint256 debtToken1; // Debt for reward token 1
        uint256 debtToken2; // Debt for reward token 2
        uint256 lastAction; // Timestamp of last reward calculation
    }

    struct UserSettings {
        address defaultHarvest1; // Number of NFTs owned by the user
        address defaultHarvest2; // Number of NFTs owned by the user
        uint256 minimumHarvest1; // Debt for reward token 1
        uint256 minimumHarvest2; // Debt for reward token 2
        uint256 fee; // Timestamp of last reward calculation
    }

    struct PoolPayout {
        uint256 amount;
        uint256 minServe;
    }

    address public mintContract = 0x1D413f843BcCB2A4439b709EDb4E0a874D535797;

    IERC20 public immutable rewardToken1 = IERC20(0xFAaC6a85C3e123AB2CF7669B1024f146cFef0b38); // First reward token
    IERC20 public immutable rewardToken2 = IERC20(0x3E79130ab714E97ee73f86a56a2427bb1A519896); // Second reward token
    IMasterChef public masterchef1 = IMasterChef(0x486fEa20eA242456b450B005ED7D019E3E984f28); // First MasterChef contract
    IMasterChef public masterchef2 = IMasterChef(0xC84FbE083713544BB4Ea85E2fe95148D076b2942); // Second MasterChef contract
    uint256 public poolID1 = 25; // Pool ID for MasterChef 1
    uint256 public poolID2 = 28; // Pool ID for MasterChef 2

    mapping(address => UserInfo) public userInfo; // User data
    mapping(address => UserSettings) public userSettings; // User data
    mapping(address => uint256) public userCredit1; // User data
    mapping(address => uint256) public userCredit2; // User data
    uint256 public accDtxPerShareToken1; // Accumulated rewards per NFT for token 1
    uint256 public accDtxPerShareToken2; // Accumulated rewards per NFT for token 2
    uint256 public lastCredit1; // Last credit from MasterChef 1
    uint256 public lastCredit2; // Last credit from MasterChef 2
    uint256 public totalNFTs; // Total NFTs in circulation
    address public treasury = 0xD540b89Ee52F81bE921Aa856bb2808A96BA9E3a1; // Governing contract

    mapping(address => PoolPayout) public poolPayout; //determines the percentage received depending on withdrawal option
    mapping(address => PoolPayout) public poolPayout2; //for degen
    uint256 public defaultDirectPayout = 50; //0.5% if withdrawn into wallet

    //default harvest settings
    address public defaultHarvest = 0xf3E82f4123d4262a2baEC25b03652f3932A91739; //5year oink
    address public defaultHarvest2 = 0xdE672FccA32365bD704c39bd1164a0D34a3a73e6; //10year degen
    uint256 public defaultMinHarvestOink = 10000;
    uint256 public defaultMinHarvestDegen = 10000000000;
    uint256 public defaultFee = 100; //1%

    address public helperToken = 0xe1cAF2F0da06A97A7f04B9Ea1B43C91F447cf343;


    event Harvest(address indexed user, uint256 amountToken1, uint256 amountToken2);
    event NFTMinted(address indexed user, uint256 amount);
    event NFTBurned(address indexed user, uint256 amount);


    constructor() ERC1155("https://raw.githubusercontent.com/DegenStrategy/DEGEN/refs/heads/main/nftMinerMetadata.json") {
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].amount = 100;
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].minServe = 864000;

        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].amount = 300;
        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].minServe = 2592000;

        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].amount = 500;
        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].minServe = 5184000;

        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].amount = 1000;
        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].minServe = 8640000;

        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].amount = 2500;
        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].minServe = 20736000;

        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].amount = 10000;
        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].minServe = 31536000; 

        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].amount = 100;
        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].minServe = 864000;

        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].amount = 250;
        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].minServe = 2592000;

        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].amount = 500;
        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].minServe = 8640000;

        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].amount = 10000;
        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].minServe = 31536000; 
    }

    // Modifier for decentralized voting
    modifier decentralizedVoting() {
        require(msg.sender == masterchef2.owner(), "Decentralized Voting Only!");
        _;
    }


    // Mint new NFT
    function mint(address _to, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _updatePool();

        UserInfo storage user = userInfo[_to];
        uint256 oldNftCount = user.nftCount;

        // Credit any existing pending before resetting debt (preserves prior accruals)
        if (oldNftCount > 0) {
            // Bank current period's share for old stack (add to any prior credit)
            userCredit1[_to] += (oldNftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12);
            userCredit2[_to] += (oldNftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12);
        } 
        // New or existing: Start whole stack with current debt (no past rewards for new portion)
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;  // Drop if unused

        _mint(_to, MINING_UNIT, _amount, "");
        user.nftCount += _amount;
        totalNFTs += _amount;
        emit NFTMinted(_to, _amount);
    }

    // Burn mining units
    function burn(address _user, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _updatePool();

        UserInfo storage user = userInfo[_user];
        uint256 oldNftCount = user.nftCount;
        require(oldNftCount >= _amount, "Insufficient NFTs");

        // Credit only the burned portion's pending to userCredit (burned gets their share)
        uint256 pending1 = _amount * (accDtxPerShareToken1 - user.debtToken1) / 1e12;
        uint256 pending2 = _amount * (accDtxPerShareToken2 - user.debtToken2) / 1e12;

        if (pending1 > 0) {
            userCredit1[_user] += pending1;
        }
        if (pending2 > 0) {
            userCredit2[_user] += pending2;
        }

        user.nftCount -= _amount;
        user.lastAction = block.timestamp;
        _burn(_user, MINING_UNIT, _amount);
        totalNFTs -= _amount;

        emit NFTBurned(_user, _amount);
    }


    function massHarvest(address[] calldata _users) external {
        for(uint256 i = 0; i< _users.length; ++i) {
            publicHarvest(_users[i]);
        }
    }

    // Harvest rewards for a user
    function publicHarvest(address _user) public  {
        _updatePool();
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        if (nftCount == 0) {
            return;
        }

        UserSettings storage userData = userSettings[_user];
        address _harvestInto = userData.defaultHarvest1;
        address _harvestInto2 = userData.defaultHarvest2;
        uint256 _minimumHarvest1 = userData.minimumHarvest1;
        uint256 _minimumHarvest2 = userData.minimumHarvest2;
        uint256 _fee = userData.fee;

        // use default settings if not set
        if(_harvestInto == address(0)) { _harvestInto = defaultHarvest; }
        if(_harvestInto2 == address(0)) { _harvestInto2 = defaultHarvest2; }
        if(_minimumHarvest1 == 0) { _minimumHarvest1 = defaultMinHarvestOink; }
        if(_minimumHarvest2 == 0) { _minimumHarvest2 = defaultMinHarvestDegen; }
        if(_fee == 1) { _fee = 0; } else if(_fee == 0) { _fee = defaultFee; } // user must set to 1 for 0 fee


        // Calculate pending rewards for both tokens
        uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];

        require(pendingToken1 >= _minimumHarvest1 && pendingToken2 >= _minimumHarvest2, "pending balance below minimum required threshold for harvest");

        // Update user's debt
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;

        uint256 _payout = 0;
        uint256 _penalty = 0;
        uint256 _harvestFee = 0;

        // Transfer rewards
        if (pendingToken1 > 0) {

            if(_harvestInto == msg.sender) {
                _payout = pendingToken1 * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(_user, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = pendingToken1 * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout[_harvestInto].minServe);
            }

            _penalty = pendingToken1 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit1 -= pendingToken1;
        }
        if (pendingToken2 > 0) {
            if(_harvestInto2 == msg.sender) {
                _payout = pendingToken2 * defaultDirectPayout / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(_user, (_payout-_harvestFee)); 
		    } else {
                require(poolPayout2[_harvestInto2].amount != 0, "incorrect pool!");
                _payout = pendingToken2 * poolPayout2[_harvestInto2].amount / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), (_payout-_harvestFee));
                IacPool(_harvestInto2).giftDeposit((_payout-_harvestFee), msg.sender, poolPayout2[_harvestInto2].minServe);
            }

            if(_harvestFee > 0) {
                IMasterChef(masterchef2).transferCredit(helperToken, _harvestFee);
		        IHelperToken(helperToken).mint(msg.sender, _harvestFee);
            }
            _penalty = pendingToken2 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit2 -= pendingToken2;
        }

        emit Harvest(_user, pendingToken1, pendingToken2);
    }

    //choose how much (the remaining gets left)
    function selfHarvest(uint256 _amount, address _harvestInto, bool _token1) external {
        _updatePool();
        UserInfo storage user = userInfo[msg.sender];
        uint256 nftCount = user.nftCount;

        require(nftCount > 0 || userCredit1[msg.sender] > 0 || userCredit2[msg.sender] > 0, "nothing to harvest!");

        uint256 _payout;
        uint256 _penalty;

        if(_token1) {
            uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[msg.sender];
            user.debtToken1 = accDtxPerShareToken1;
            user.lastAction = block.timestamp;
            if(pendingToken1 < _amount) { _amount = pendingToken1; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit1[msg.sender] = pendingToken1 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit1 -= _amount;
            emit Harvest(msg.sender, _amount, 0);
        } else { // token2 (degen)
            uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[msg.sender];
            user.debtToken2 = accDtxPerShareToken2;
            user.lastAction = block.timestamp;
            if(pendingToken2 < _amount) { _amount = pendingToken2; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit2[msg.sender] = pendingToken2 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef2).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout2[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout2[_harvestInto].amount / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout2[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }

            lastCredit2 -= _amount;
            emit Harvest(msg.sender, 0, _amount);
        }
    }

    // Update pool rewards for both MasterChefs
    function _updatePool() internal {
        // Update MasterChef 1
        masterchef1.updatePool(poolID1);
        uint256 currentCredit1 = masterchef1.credit(address(this));
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;
        lastCredit1 = currentCredit1;


        // Update MasterChef 2
        masterchef2.updatePool(poolID2);
        uint256 currentCredit2 = masterchef2.credit(address(this));
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;
        lastCredit2 = currentCredit2;
        if (totalNFTs > 0) {
            accDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            accDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }
    }

    // Hook called before any NFT transfer
        function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal virtual override {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);
        require(from != to, "Cannot transfer to self");

        if (from == address(0) || to == address(0)) {
            return; // Minting or burning, no need to update rewards
        }

        _updatePool();

        // Ensure single token ID (MINING_UNIT) is being transferred
        require(ids.length == 1 && ids[0] == MINING_UNIT, "Only MINING_UNIT transfers allowed");
        uint256 amount = amounts[0];

        // Harvest for sender
        if (from != address(0)) {
            UserInfo storage fromUser = userInfo[from];
            uint256 nftCount = fromUser.nftCount;
            if (nftCount > 0) {
                uint256 pendingToken1 = nftCount * (accDtxPerShareToken1 - fromUser.debtToken1) / 1e12;
                uint256 pendingToken2 = nftCount * (accDtxPerShareToken2 - fromUser.debtToken2) / 1e12;

                fromUser.debtToken1 = accDtxPerShareToken1;
                fromUser.debtToken2 = accDtxPerShareToken2;
                fromUser.lastAction = block.timestamp;

                if (pendingToken1 > 0) {
                    userCredit1[from] += pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[from] += pendingToken2;
                }
            }
            fromUser.nftCount -= amount;
        }

        // Update recipient's info
        if (to != address(0)) {
            UserInfo storage toUser = userInfo[to];
            if (toUser.nftCount > 0) {
                uint256 pendingToken1 = toUser.nftCount * (accDtxPerShareToken1 - toUser.debtToken1) / 1e12;
                uint256 pendingToken2 = toUser.nftCount * (accDtxPerShareToken2 - toUser.debtToken2) / 1e12;

                if (pendingToken1 > 0) {
                    userCredit1[to] += pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[to] += pendingToken2;
                }
            }
            toUser.nftCount += amount;
            toUser.debtToken1 = accDtxPerShareToken1;
            toUser.debtToken2 = accDtxPerShareToken2;
            toUser.lastAction = block.timestamp;
        }
    }

    // View function to check pending rewards for a user
    function viewUserTotalEarnings(address _user) external view returns (uint256 pendingToken1, uint256 pendingToken2) {
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        uint256 currentCredit1 = masterchef1.credit(address(this)) + masterchef1.pendingDtx(poolID1);
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;

        uint256 currentCredit2 = masterchef2.credit(address(this)) + masterchef2.pendingDtx(poolID2);
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;

        uint256 virtualAccDtxPerShareToken1 = accDtxPerShareToken1;
        uint256 virtualAccDtxPerShareToken2 = accDtxPerShareToken2;

        if (totalNFTs > 0) {
            virtualAccDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            virtualAccDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }

        pendingToken1 = (nftCount * (virtualAccDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        pendingToken2 = (nftCount * (virtualAccDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];
    }

    // Update MasterChef addresses
    function setMasterChefAddresses(IMasterChef _masterchef1, IMasterChef _masterchef2, uint256 _poolID1, uint256 _poolID2) external decentralizedVoting {
        masterchef1 = _masterchef1;
        masterchef2 = _masterchef2;
        poolID1 = _poolID1;
        poolID2 = _poolID2;
    }

    // Update treasury address
    function updateTreasury(address _treasury) external decentralizedVoting {
        treasury = _treasury;
    }

    function setUserSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external {
        UserSettings storage userData = userSettings[msg.sender];
        require(_fee <= 2500, "Fee must be less than or equal to 25%");
        userData.fee = _fee;
        userData.defaultHarvest1 = _defaultharvest;
        userData.defaultHarvest2 = _defaultHarvest2;
        userData.minimumHarvest1 = _defaultMinHarvestOink;
        userData.minimumHarvest2 = _defaultminHarvestDegen;
    }

    function setDefaultSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external decentralizedVoting {
        require(_fee <= 500, "Fee must be less than or equal to 5%");
        defaultFee = _fee;
        defaultHarvest = _defaultharvest;
        defaultHarvest2 = _defaultHarvest2;
        defaultMinHarvestOink = _defaultMinHarvestOink;
        defaultMinHarvestDegen = _defaultminHarvestDegen;
    }

    function setPoolPayout(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout[_pool].amount = _amount;
        poolPayout[_pool].minServe = _minServe;
    }
    function setPoolPayout2(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout2[_pool].amount = _amount;
        poolPayout2[_pool].minServe = _minServe;
    }
    function setMintContract(address _a) external decentralizedVoting {
        mintContract = _a;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/token/ERC1155/ERC1155.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/token/ERC20/IERC20.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/token/ERC20/utils/SafeERC20.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/security/ReentrancyGuard.sol";

import "../interface/IMasterChef.sol";
import "../interface/IacPool.sol";

interface IHelperToken {
	function mint(address to, uint256 amount) external;
}

contract NFTVault is ERC1155, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MINING_UNIT = 1; // Single token ID for all identical mining units


    struct UserInfo {
        uint256 nftCount; // Number of NFTs owned by the user
        uint256 debtToken1; // Debt for reward token 1
        uint256 debtToken2; // Debt for reward token 2
        uint256 lastAction; // Timestamp of last reward calculation
    }

    struct UserSettings {
        address defaultHarvest1; // Number of NFTs owned by the user
        address defaultHarvest2; // Number of NFTs owned by the user
        uint256 minimumHarvest1; // Debt for reward token 1
        uint256 minimumHarvest2; // Debt for reward token 2
        uint256 fee; // Timestamp of last reward calculation
    }

    struct PoolPayout {
        uint256 amount;
        uint256 minServe;
    }

    address public mintContract = 0x8fB7B030743057F3aa54BE27Bb1c36d4a08E17be;

    IERC20 public immutable rewardToken1 = IERC20(0xFAaC6a85C3e123AB2CF7669B1024f146cFef0b38); // First reward token
    IERC20 public immutable rewardToken2 = IERC20(0x3E79130ab714E97ee73f86a56a2427bb1A519896); // Second reward token
    IMasterChef public masterchef1 = IMasterChef(0x486fEa20eA242456b450B005ED7D019E3E984f28); // First MasterChef contract
    IMasterChef public masterchef2 = IMasterChef(0xC84FbE083713544BB4Ea85E2fe95148D076b2942); // Second MasterChef contract
    uint256 public poolID1 = 26; // Pool ID for MasterChef 1
    uint256 public poolID2 = 31; // Pool ID for MasterChef 2

    mapping(address => UserInfo) public userInfo; // User data
    mapping(address => UserSettings) public userSettings; // User data
    mapping(address => uint256) public userCredit1; // User data
    mapping(address => uint256) public userCredit2; // User data
    uint256 public accDtxPerShareToken1; // Accumulated rewards per NFT for token 1
    uint256 public accDtxPerShareToken2; // Accumulated rewards per NFT for token 2
    uint256 public lastCredit1; // Last credit from MasterChef 1
    uint256 public lastCredit2; // Last credit from MasterChef 2
    uint256 public totalNFTs; // Total NFTs in circulation
    address public treasury = 0xD540b89Ee52F81bE921Aa856bb2808A96BA9E3a1; // Governing contract

    mapping(address => PoolPayout) public poolPayout; //determines the percentage received depending on withdrawal option
    mapping(address => PoolPayout) public poolPayout2; //for degen
    uint256 public defaultDirectPayout = 50; //0.5% if withdrawn into wallet

    //default harvest settings
    address public defaultHarvest = 0xf3E82f4123d4262a2baEC25b03652f3932A91739; //5year oink
    address public defaultHarvest2 = 0xdE672FccA32365bD704c39bd1164a0D34a3a73e6; //10year degen
    uint256 public defaultMinHarvestOink = 2000000000000000000000;
    uint256 public defaultMinHarvestDegen = 10000000000000000000000000;
    uint256 public defaultFee = 100; //1%

    address public helperToken = 0xe1cAF2F0da06A97A7f04B9Ea1B43C91F447cf343;


    event Harvest(address indexed user, uint256 amountToken1, uint256 amountToken2);
    event NFTMinted(address indexed user, uint256 amount);
    event NFTBurned(address indexed user, uint256 amount);


    constructor() ERC1155("https://raw.githubusercontent.com/DegenStrategy/DEGEN/refs/heads/main/nftMinerMetadata.json") {
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].amount = 100;
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].minServe = 864000;

        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].amount = 300;
        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].minServe = 2592000;

        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].amount = 500;
        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].minServe = 5184000;

        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].amount = 1000;
        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].minServe = 8640000;

        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].amount = 2500;
        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].minServe = 20736000;

        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].amount = 10000;
        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].minServe = 31536000; 

        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].amount = 100;
        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].minServe = 864000;

        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].amount = 250;
        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].minServe = 2592000;

        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].amount = 500;
        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].minServe = 8640000;

        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].amount = 10000;
        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].minServe = 31536000; 
    }

    // Modifier for decentralized voting
    modifier decentralizedVoting() {
        require(msg.sender == masterchef2.owner(), "Decentralized Voting Only!");
        _;
    }


    // Mint new NFT
    function mint(address _to, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _updatePool();
        
        UserInfo storage user = userInfo[_to];
        uint256 oldNftCount = user.nftCount;
        
        // Credit any existing pending before resetting debt (preserves prior accruals)
        if (oldNftCount > 0) {
            // Bank current period's share for old stack (add to any prior credit)
            userCredit1[_to] += (oldNftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12);
            userCredit2[_to] += (oldNftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12);
        } 
        // New or existing: Start whole stack with current debt (no past rewards for new portion)
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;  // Drop if unused
        
        _mint(_to, MINING_UNIT, _amount, "");
        user.nftCount += _amount;
        totalNFTs += _amount;
        emit NFTMinted(_to, _amount);
    }

    // Burn mining units
    function burn(address _user, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _updatePool();
        
        UserInfo storage user = userInfo[_user];
        uint256 oldNftCount = user.nftCount;
        require(oldNftCount >= _amount, "Insufficient NFTs");
        
        // Credit only the burned portion's pending to userCredit (burned gets their share)
        uint256 pending1 = _amount * (accDtxPerShareToken1 - user.debtToken1) / 1e12;
        uint256 pending2 = _amount * (accDtxPerShareToken2 - user.debtToken2) / 1e12;
        
        if (pending1 > 0) {
            userCredit1[_user] += pending1;
        }
        if (pending2 > 0) {
            userCredit2[_user] += pending2;
        }
        
        user.nftCount -= _amount;
        user.lastAction = block.timestamp;
        _burn(_user, MINING_UNIT, _amount);
        totalNFTs -= _amount;
        
        emit NFTBurned(_user, _amount);
    }


    function massHarvest(address[] calldata _users) external {
        for(uint256 i = 0; i< _users.length; ++i) {
            publicHarvest(_users[i]);
        }
    }

    // Harvest rewards for a user
    function publicHarvest(address _user) public  {
        _updatePool();
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        if (nftCount == 0) {
            return;
        }

        UserSettings storage userData = userSettings[_user];
        address _harvestInto = userData.defaultHarvest1;
        address _harvestInto2 = userData.defaultHarvest2;
        uint256 _minimumHarvest1 = userData.minimumHarvest1;
        uint256 _minimumHarvest2 = userData.minimumHarvest2;
        uint256 _fee = userData.fee;

        // use default settings if not set
        if(_harvestInto == address(0)) { _harvestInto = defaultHarvest; }
        if(_harvestInto2 == address(0)) { _harvestInto2 = defaultHarvest2; }
        if(_minimumHarvest1 == 0) { _minimumHarvest1 = defaultMinHarvestOink; }
        if(_minimumHarvest2 == 0) { _minimumHarvest2 = defaultMinHarvestDegen; }
        if(_fee == 1) { _fee = 0; } else if(_fee == 0) { _fee = defaultFee; } // user must set to 1 for 0 fee


        // Calculate pending rewards for both tokens
        uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];

        require(pendingToken1 >= _minimumHarvest1 && pendingToken2 >= _minimumHarvest2, "pending balance below minimum required threshold for harvest");

        // Update user's debt
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;

        uint256 _payout = 0;
        uint256 _penalty = 0;
        uint256 _harvestFee = 0;

        // Transfer rewards
        if (pendingToken1 > 0) {

            if(_harvestInto == _user) {
                _payout = pendingToken1 * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(_user, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = pendingToken1 * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, _user, poolPayout[_harvestInto].minServe);
            }

            _penalty = pendingToken1 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit1 -= pendingToken1;
        }
        if (pendingToken2 > 0) {
            if(_harvestInto2 == _user) {
                _payout = pendingToken2 * defaultDirectPayout / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(_user, (_payout-_harvestFee)); 
		    } else {
                require(poolPayout2[_harvestInto2].amount != 0, "incorrect pool!");
                _payout = pendingToken2 * poolPayout2[_harvestInto2].amount / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), (_payout-_harvestFee));
                IacPool(_harvestInto2).giftDeposit((_payout-_harvestFee), _user, poolPayout2[_harvestInto2].minServe);
            }

            if(_harvestFee > 0) {
                IMasterChef(masterchef2).transferCredit(helperToken, _harvestFee);
		        IHelperToken(helperToken).mint(msg.sender, _harvestFee);
            }
            _penalty = pendingToken2 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit2 -= pendingToken2;
        }

        emit Harvest(_user, pendingToken1, pendingToken2);
    }

    //choose how much (the remaining gets left)
    function selfHarvest(uint256 _amount, address _harvestInto, bool _token1) external {
        _updatePool();
        UserInfo storage user = userInfo[msg.sender];
        uint256 nftCount = user.nftCount;

        require(nftCount > 0 || userCredit1[msg.sender] > 0 || userCredit2[msg.sender] > 0, "nothing to harvest!");

        uint256 _payout;
        uint256 _penalty;

        if(_token1) {
            uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[msg.sender];
            user.debtToken1 = accDtxPerShareToken1;
            user.lastAction = block.timestamp;
            if(pendingToken1 < _amount) { _amount = pendingToken1; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit1[msg.sender] = pendingToken1 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit1 -= _amount;
            emit Harvest(msg.sender, _amount, 0);
        } else { // token2 (degen)
            uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[msg.sender];
            user.debtToken2 = accDtxPerShareToken2;
            user.lastAction = block.timestamp;
            if(pendingToken2 < _amount) { _amount = pendingToken2; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit2[msg.sender] = pendingToken2 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef2).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout2[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout2[_harvestInto].amount / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout2[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit2 -= _amount;
            emit Harvest(msg.sender, 0, _amount);
        }
    }

    // Update pool rewards for both MasterChefs
    function _updatePool() internal {
        // Update MasterChef 1
        masterchef1.updatePool(poolID1);
        uint256 currentCredit1 = masterchef1.credit(address(this));
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;
        lastCredit1 = currentCredit1;


        // Update MasterChef 2
        masterchef2.updatePool(poolID2);
        uint256 currentCredit2 = masterchef2.credit(address(this));
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;
        lastCredit2 = currentCredit2;
        if (totalNFTs > 0) {
            accDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            accDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }
    }

    // Hook called before any NFT transfer
        function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal virtual override {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);
        require(from != to, "Cannot transfer to self");

        if (from == address(0) || to == address(0)) {
            return; // Minting or burning, no need to update rewards
        }

        _updatePool();

        // Ensure single token ID (MINING_UNIT) is being transferred
        require(ids.length == 1 && ids[0] == MINING_UNIT, "Only MINING_UNIT transfers allowed");
        uint256 amount = amounts[0];

        // Harvest for sender
        if (from != address(0)) {
            UserInfo storage fromUser = userInfo[from];
            uint256 nftCount = fromUser.nftCount;
            if (nftCount > 0) {
                uint256 pendingToken1 = nftCount * (accDtxPerShareToken1 - fromUser.debtToken1) / 1e12;
                uint256 pendingToken2 = nftCount * (accDtxPerShareToken2 - fromUser.debtToken2) / 1e12;

                fromUser.debtToken1 = accDtxPerShareToken1;
                fromUser.debtToken2 = accDtxPerShareToken2;
                fromUser.lastAction = block.timestamp;

                if (pendingToken1 > 0) {
                    userCredit1[from] += pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[from] += pendingToken2;
                }
            }
            fromUser.nftCount -= amount;
        }

        // Update recipient's info
        if (to != address(0)) {
            UserInfo storage toUser = userInfo[to];
            if (toUser.nftCount > 0) {
                uint256 pendingToken1 = toUser.nftCount * (accDtxPerShareToken1 - toUser.debtToken1) / 1e12;
                uint256 pendingToken2 = toUser.nftCount * (accDtxPerShareToken2 - toUser.debtToken2) / 1e12;

                if (pendingToken1 > 0) {
                    userCredit1[to] += pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[to] += pendingToken2;
                }
            }
            toUser.nftCount += amount;
            toUser.debtToken1 = accDtxPerShareToken1;
            toUser.debtToken2 = accDtxPerShareToken2;
            toUser.lastAction = block.timestamp;
        }
    }

    // View function to check pending rewards for a user
    function viewUserTotalEarnings(address _user) external view returns (uint256 pendingToken1, uint256 pendingToken2) {
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        uint256 currentCredit1 = masterchef1.credit(address(this)) + masterchef1.pendingDtx(poolID1);
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;

        uint256 currentCredit2 = masterchef2.credit(address(this)) + masterchef2.pendingDtx(poolID2);
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;

        uint256 virtualAccDtxPerShareToken1 = accDtxPerShareToken1;
        uint256 virtualAccDtxPerShareToken2 = accDtxPerShareToken2;

        if (totalNFTs > 0) {
            virtualAccDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            virtualAccDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }

        pendingToken1 = (nftCount * (virtualAccDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        pendingToken2 = (nftCount * (virtualAccDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];
    }

    // Update MasterChef addresses
    function setMasterChefAddresses(IMasterChef _masterchef1, IMasterChef _masterchef2, uint256 _poolID1, uint256 _poolID2) external decentralizedVoting {
        masterchef1 = _masterchef1;
        masterchef2 = _masterchef2;
        poolID1 = _poolID1;
        poolID2 = _poolID2;
    }

    // Update treasury address
    function updateTreasury(address _treasury) external decentralizedVoting {
        treasury = _treasury;
    }

    function setUserSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external {
        UserSettings storage userData = userSettings[msg.sender];
        require(_fee <= 2500, "Fee must be less than or equal to 25%");
        userData.fee = _fee;
        userData.defaultHarvest1 = _defaultharvest;
        userData.defaultHarvest2 = _defaultHarvest2;
        userData.minimumHarvest1 = _defaultMinHarvestOink;
        userData.minimumHarvest2 = _defaultminHarvestDegen;
    }

    function setDefaultSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external decentralizedVoting {
        require(_fee <= 500, "Fee must be less than or equal to 5%");
        defaultFee = _fee;
        defaultHarvest = _defaultharvest;
        defaultHarvest2 = _defaultHarvest2;
        defaultMinHarvestOink = _defaultMinHarvestOink;
        defaultMinHarvestDegen = _defaultminHarvestDegen;
    }

    function setPoolPayout(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout[_pool].amount = _amount;
        poolPayout[_pool].minServe = _minServe;
    }
    function setPoolPayout2(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout2[_pool].amount = _amount;
        poolPayout2[_pool].minServe = _minServe;
    }
    function setMintContract(address _a) external decentralizedVoting {
        mintContract = _a;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/token/ERC1155/ERC1155.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/token/ERC20/IERC20.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/token/ERC20/utils/SafeERC20.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.9.3/contracts/security/ReentrancyGuard.sol";

import "../interface/IMasterChef.sol";
import "../interface/IacPool.sol";

interface IHelperToken {
	function mint(address to, uint256 amount) external;
}

interface INftVault {
    function userSettings(address) external view returns(address,address,uint256,uint256,uint256);
}

contract NFTVault is ERC1155, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MINING_UNIT = 1; // Single token ID for all identical mining units


    struct UserInfo {
        uint256 nftCount; // Number of NFTs owned by the user
        uint256 debtToken1; // Debt for reward token 1
        uint256 debtToken2; // Debt for reward token 2
        uint256 lastAction; // Timestamp of last reward calculation
    }

    struct UserSettings {
        address defaultHarvest1; // Number of NFTs owned by the user
        address defaultHarvest2; // Number of NFTs owned by the user
        uint256 minimumHarvest1; // Debt for reward token 1
        uint256 minimumHarvest2; // Debt for reward token 2
        uint256 fee; // Timestamp of last reward calculation
    }

    struct PoolPayout {
        uint256 amount;
        uint256 minServe;
    }

    address public mintContract = 0x141a8649e3CAEb3a1589ba4922cDb651b6706281;

    IERC20 public immutable rewardToken1 = IERC20(0xFAaC6a85C3e123AB2CF7669B1024f146cFef0b38); // First reward token
    IERC20 public immutable rewardToken2 = IERC20(0x3E79130ab714E97ee73f86a56a2427bb1A519896); // Second reward token
    IMasterChef public masterchef1 = IMasterChef(0x486fEa20eA242456b450B005ED7D019E3E984f28); // First MasterChef contract
    IMasterChef public masterchef2 = IMasterChef(0xC84FbE083713544BB4Ea85E2fe95148D076b2942); // Second MasterChef contract
    uint256 public poolID1 = 27; // Pool ID for MasterChef 1
    uint256 public poolID2 = 32; // Pool ID for MasterChef 2

    mapping(address => UserInfo) public userInfo; // User data
    mapping(address => UserSettings) public userSettings; // User data
    mapping(address => uint256) public userCredit1; // User data
    mapping(address => uint256) public userCredit2; // User data
    uint256 public accDtxPerShareToken1; // Accumulated rewards per NFT for token 1
    uint256 public accDtxPerShareToken2; // Accumulated rewards per NFT for token 2
    uint256 public lastCredit1; // Last credit from MasterChef 1
    uint256 public lastCredit2; // Last credit from MasterChef 2
    uint256 public totalNFTs; // Total NFTs in circulation
    address public treasury = 0xD540b89Ee52F81bE921Aa856bb2808A96BA9E3a1; // Governing contract

    mapping(address => PoolPayout) public poolPayout; //determines the percentage received depending on withdrawal option
    mapping(address => PoolPayout) public poolPayout2; //for degen
    uint256 public defaultDirectPayout = 50; //0.5% if withdrawn into wallet

    //default harvest settings
    address public defaultHarvest = 0xf3E82f4123d4262a2baEC25b03652f3932A91739; //5year oink
    address public defaultHarvest2 = 0xdE672FccA32365bD704c39bd1164a0D34a3a73e6; //10year degen
    uint256 public defaultMinHarvestOink = 2000000000000000000000;
    uint256 public defaultMinHarvestDegen = 10000000000000000000000000;
    uint256 public defaultFee = 100; //1%

    address public helperToken = 0xe1cAF2F0da06A97A7f04B9Ea1B43C91F447cf343;

    //disabled after initialization
    bool public canUpdateUserSettings = true;
    bool public migrateNftVaultContract = false; //in case NFT contract is updated, can harvest earnings without limits
    address deployer;

    event Harvest(address indexed user, uint256 amountToken1, uint256 amountToken2);
    event NFTMinted(address indexed user, uint256 amount);
    event NFTBurned(address indexed user, uint256 amount);


    constructor() ERC1155("https://raw.githubusercontent.com/DegenStrategy/DEGEN/refs/heads/main/nftMinerMetadata.json") {
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].amount = 100;
        poolPayout[0x39b3E852D6fFA1aF6694Ef87C062450de6778da8].minServe = 864000;

        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].amount = 300;
        poolPayout[0x9013B1067C52E897E713044dE36c56BfdA8Ec9B4].minServe = 2592000;

        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].amount = 500;
        poolPayout[0xb180450f064E79adBFD71Bc2fB086F9CD0Af0D67].minServe = 5184000;

        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].amount = 1000;
        poolPayout[0xc0483f1b0dcf601888fFD0d3A44b7124e80DB7D1].minServe = 8640000;

        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].amount = 2500;
        poolPayout[0x15b51Ece819f3B51ce814de67bB2419660701a3c].minServe = 20736000;

        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].amount = 10000;
        poolPayout[0xf3E82f4123d4262a2baEC25b03652f3932A91739].minServe = 31536000; 

        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].amount = 100;
        poolPayout2[0xD9B491ac0f5487673500B67224b67b4171a08aCa].minServe = 864000;

        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].amount = 250;
        poolPayout2[0x7ED33f65A0398cb26eaB2B03877825c96D9B6077].minServe = 2592000;

        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].amount = 500;
        poolPayout2[0x3d175C8359169b0e830d36EA9CD3FE209f46f7BD].minServe = 8640000;

        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].amount = 10000;
        poolPayout2[0xdE672FccA32365bD704c39bd1164a0D34a3a73e6].minServe = 31536000; 

        deployer = msg.sender;
    }

    // Modifier for decentralized voting
    modifier decentralizedVoting() {
        require(msg.sender == masterchef2.owner(), "Decentralized Voting Only!");
        _;
    }


    // Mint new NFT
    function mint(address _to, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _updatePool();
        
        UserInfo storage user = userInfo[_to];
        uint256 oldNftCount = user.nftCount;
        
        // Credit any existing pending before resetting debt (preserves prior accruals)
        if (oldNftCount > 0) {
            // Bank current period's share for old stack (add to any prior credit)
            userCredit1[_to] += (oldNftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12);
            userCredit2[_to] += (oldNftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12);
        } 
        // New or existing: Start whole stack with current debt (no past rewards for new portion)
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;  // Drop if unused
        
        _mint(_to, MINING_UNIT, _amount, "");
        user.nftCount += _amount;
        totalNFTs += _amount;
        emit NFTMinted(_to, _amount);
    }

    // Burn mining units
    function burn(address _user, uint256 _amount) external {
        require(msg.sender == mintContract, "Only mint contract allowed!");
        require(_amount > 0, "Amount must be greater than 0!");
        _updatePool();
        
        UserInfo storage user = userInfo[_user];
        uint256 oldNftCount = user.nftCount;
        require(oldNftCount >= _amount, "Insufficient NFTs");
        
        // Credit only the burned portion's pending to userCredit (burned gets their share)
        uint256 pending1 = _amount * (accDtxPerShareToken1 - user.debtToken1) / 1e12;
        uint256 pending2 = _amount * (accDtxPerShareToken2 - user.debtToken2) / 1e12;
        
        if (pending1 > 0) {
            userCredit1[_user] += pending1;
        }
        if (pending2 > 0) {
            userCredit2[_user] += pending2;
        }
        
        user.nftCount -= _amount;
        user.lastAction = block.timestamp;
        _burn(_user, MINING_UNIT, _amount);
        totalNFTs -= _amount;
        
        emit NFTBurned(_user, _amount);
    }


    function massHarvest(address[] calldata _users) external {
        for(uint256 i = 0; i< _users.length; ++i) {
            publicHarvest(_users[i]);
        }
    }

    // Harvest rewards for a user
    function publicHarvest(address _user) public  {
        _updatePool();
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        if (nftCount == 0) {
            return;
        }

        UserSettings storage userData = userSettings[_user];
        address _harvestInto = userData.defaultHarvest1;
        address _harvestInto2 = userData.defaultHarvest2;
        uint256 _minimumHarvest1 = userData.minimumHarvest1;
        uint256 _minimumHarvest2 = userData.minimumHarvest2;
        uint256 _fee = userData.fee;

        // use default settings if not set
        if(_harvestInto == address(0)) { _harvestInto = defaultHarvest; }
        if(_harvestInto2 == address(0)) { _harvestInto2 = defaultHarvest2; }
        if(_minimumHarvest1 == 0) { _minimumHarvest1 = defaultMinHarvestOink; }
        if(_minimumHarvest2 == 0) { _minimumHarvest2 = defaultMinHarvestDegen; }
        if(_fee == 1) { _fee = 0; } else if(_fee == 0) { _fee = defaultFee; } // user must set to 1 for 0 fee


        // Calculate pending rewards for both tokens
        uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];

        if(!migrateNftVaultContract) {
            require(pendingToken1 >= _minimumHarvest1 && pendingToken2 >= _minimumHarvest2, "pending balance below minimum required threshold for harvest");
        } else {
            _fee = 0;
        }

        userCredit1[_user] = 0;
        userCredit2[_user] = 0;

        // Update user's debt
        user.debtToken1 = accDtxPerShareToken1;
        user.debtToken2 = accDtxPerShareToken2;
        user.lastAction = block.timestamp;

        uint256 _payout = 0;
        uint256 _penalty = 0;
        uint256 _harvestFee = 0;

        // Transfer rewards
        if (pendingToken1 > 0) {

            if(_harvestInto == _user) {
                _payout = pendingToken1 * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(_user, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = pendingToken1 * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, _user, poolPayout[_harvestInto].minServe);
            }

            _penalty = pendingToken1 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit1 -= pendingToken1;
        }
        if (pendingToken2 > 0) {
            if(_harvestInto2 == _user) {
                _payout = pendingToken2 * defaultDirectPayout / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(_user, (_payout-_harvestFee)); 
		    } else {
                require(poolPayout2[_harvestInto2].amount != 0, "incorrect pool!");
                _payout = pendingToken2 * poolPayout2[_harvestInto2].amount / 10000;
                _harvestFee = _payout * _fee / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), (_payout-_harvestFee));
                IacPool(_harvestInto2).giftDeposit((_payout-_harvestFee), _user, poolPayout2[_harvestInto2].minServe);
            }

            if(_harvestFee > 0) {
                IMasterChef(masterchef2).transferCredit(helperToken, _harvestFee);
		        IHelperToken(helperToken).mint(msg.sender, _harvestFee);
            }
            _penalty = pendingToken2 - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit2 -= pendingToken2;
        }

        emit Harvest(_user, pendingToken1, pendingToken2);
    }

    //choose how much (the remaining gets left)
    function selfHarvest(uint256 _amount, address _harvestInto, bool _token1) external {
        _updatePool();
        UserInfo storage user = userInfo[msg.sender];
        uint256 nftCount = user.nftCount;

        require(nftCount > 0 || userCredit1[msg.sender] > 0 || userCredit2[msg.sender] > 0, "nothing to harvest!");

        uint256 _payout;
        uint256 _penalty;

        if(_token1) {
            uint256 pendingToken1 = (nftCount * (accDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[msg.sender];
            user.debtToken1 = accDtxPerShareToken1;
            user.lastAction = block.timestamp;
            if(pendingToken1 < _amount) { _amount = pendingToken1; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit1[msg.sender] = pendingToken1 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef1).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout[_harvestInto].amount / 10000;
                IMasterChef(masterchef1).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef1).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit1 -= _amount;
            emit Harvest(msg.sender, _amount, 0);
        } else { // token2 (degen)
            uint256 pendingToken2 = (nftCount * (accDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[msg.sender];
            user.debtToken2 = accDtxPerShareToken2;
            user.lastAction = block.timestamp;
            if(pendingToken2 < _amount) { _amount = pendingToken2; } //withdraw all
            require(_amount > 0, "amount must be above 0");
            userCredit2[msg.sender] = pendingToken2 - _amount; // give user remaining credit

            if(_harvestInto == msg.sender) {
                _payout = _amount * defaultDirectPayout / 10000;
                IMasterChef(masterchef2).publishTokens(msg.sender, _payout); 
		    } else {
                require(poolPayout2[_harvestInto].amount != 0, "incorrect pool!");
                _payout = _amount * poolPayout2[_harvestInto].amount / 10000;
                IMasterChef(masterchef2).publishTokens(address(this), _payout);
                IacPool(_harvestInto).giftDeposit(_payout, msg.sender, poolPayout2[_harvestInto].minServe);
            }

            _penalty = _amount - _payout;
            if(_penalty > 0) {
                IMasterChef(masterchef2).publishTokens(treasury, _penalty); //penalty to treasury
            }
            
            lastCredit2 -= _amount;
            emit Harvest(msg.sender, 0, _amount);
        }
    }

    // Update pool rewards for both MasterChefs
    function _updatePool() internal {
        // Update MasterChef 1
        masterchef1.updatePool(poolID1);
        uint256 currentCredit1 = masterchef1.credit(address(this));
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;
        lastCredit1 = currentCredit1;


        // Update MasterChef 2
        masterchef2.updatePool(poolID2);
        uint256 currentCredit2 = masterchef2.credit(address(this));
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;
        lastCredit2 = currentCredit2;
        if (totalNFTs > 0) {
            accDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            accDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }
    }

    // Hook called before any NFT transfer
        function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal virtual override {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);
        require(from != to, "Cannot transfer to self");

        if (from == address(0) || to == address(0)) {
            return; // Minting or burning, no need to update rewards
        }

        _updatePool();

        // Ensure single token ID (MINING_UNIT) is being transferred
        require(ids.length == 1 && ids[0] == MINING_UNIT, "Only MINING_UNIT transfers allowed");
        uint256 amount = amounts[0];

        // Harvest for sender
        if (from != address(0)) {
            UserInfo storage fromUser = userInfo[from];
            uint256 nftCount = fromUser.nftCount;
            if (nftCount > 0) {
                uint256 pendingToken1 = nftCount * (accDtxPerShareToken1 - fromUser.debtToken1) / 1e12;
                uint256 pendingToken2 = nftCount * (accDtxPerShareToken2 - fromUser.debtToken2) / 1e12;

                fromUser.debtToken1 = accDtxPerShareToken1;
                fromUser.debtToken2 = accDtxPerShareToken2;
                fromUser.lastAction = block.timestamp;

                if (pendingToken1 > 0) {
                    userCredit1[from] += pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[from] += pendingToken2;
                }
            }
            fromUser.nftCount -= amount;
        }

        // Update recipient's info
        if (to != address(0)) {
            UserInfo storage toUser = userInfo[to];
            if (toUser.nftCount > 0) {
                uint256 pendingToken1 = toUser.nftCount * (accDtxPerShareToken1 - toUser.debtToken1) / 1e12;
                uint256 pendingToken2 = toUser.nftCount * (accDtxPerShareToken2 - toUser.debtToken2) / 1e12;

                if (pendingToken1 > 0) {
                    userCredit1[to] += pendingToken1;
                }
                if (pendingToken2 > 0) {
                    userCredit2[to] += pendingToken2;
                }
            }
            toUser.nftCount += amount;
            toUser.debtToken1 = accDtxPerShareToken1;
            toUser.debtToken2 = accDtxPerShareToken2;
            toUser.lastAction = block.timestamp;
        }
    }

    // View function to check pending rewards for a user
    function viewUserTotalEarnings(address _user) external view returns (uint256 pendingToken1, uint256 pendingToken2) {
        UserInfo storage user = userInfo[_user];
        uint256 nftCount = user.nftCount;

        uint256 currentCredit1 = masterchef1.credit(address(this)) + masterchef1.pendingDtx(poolID1);
        uint256 accumulatedRewards1 = currentCredit1 - lastCredit1;

        uint256 currentCredit2 = masterchef2.credit(address(this)) + masterchef2.pendingDtx(poolID2);
        uint256 accumulatedRewards2 = currentCredit2 - lastCredit2;

        uint256 virtualAccDtxPerShareToken1 = accDtxPerShareToken1;
        uint256 virtualAccDtxPerShareToken2 = accDtxPerShareToken2;

        if (totalNFTs > 0) {
            virtualAccDtxPerShareToken1 += accumulatedRewards1 * 1e12 / totalNFTs;
            virtualAccDtxPerShareToken2 += accumulatedRewards2 * 1e12 / totalNFTs;
        }

        pendingToken1 = (nftCount * (virtualAccDtxPerShareToken1 - user.debtToken1) / 1e12) + userCredit1[_user];
        pendingToken2 = (nftCount * (virtualAccDtxPerShareToken2 - user.debtToken2) / 1e12) + userCredit2[_user];
    }

    // Update MasterChef addresses
    function setMasterChefAddresses(IMasterChef _masterchef1, IMasterChef _masterchef2, uint256 _poolID1, uint256 _poolID2) external decentralizedVoting {
        masterchef1 = _masterchef1;
        masterchef2 = _masterchef2;
        poolID1 = _poolID1;
        poolID2 = _poolID2;
    }

    // Update treasury address
    function updateTreasury(address _treasury) external decentralizedVoting {
        treasury = _treasury;
    }

    function setUserSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external {
        UserSettings storage userData = userSettings[msg.sender];
        require(_fee <= 2500, "Fee must be less than or equal to 25%");
        userData.fee = _fee;
        userData.defaultHarvest1 = _defaultharvest;
        userData.defaultHarvest2 = _defaultHarvest2;
        userData.minimumHarvest1 = _defaultMinHarvestOink;
        userData.minimumHarvest2 = _defaultminHarvestDegen;
    }

    function setDefaultSettings(address _defaultharvest, address _defaultHarvest2,uint256 _defaultMinHarvestOink, uint256 _defaultminHarvestDegen, uint256 _fee) external decentralizedVoting {
        require(_fee <= 500, "Fee must be less than or equal to 5%");
        defaultFee = _fee;
        defaultHarvest = _defaultharvest;
        defaultHarvest2 = _defaultHarvest2;
        defaultMinHarvestOink = _defaultMinHarvestOink;
        defaultMinHarvestDegen = _defaultminHarvestDegen;
    }

    function setPoolPayout(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout[_pool].amount = _amount;
        poolPayout[_pool].minServe = _minServe;
    }
    function setPoolPayout2(address _pool, uint256 _amount, uint256 _minServe) external decentralizedVoting {
        poolPayout2[_pool].amount = _amount;
        poolPayout2[_pool].minServe = _minServe;
    }
    function setMintContract(address _a) external decentralizedVoting {
        mintContract = _a;
    }
    function enableNftVaultMigration() external decentralizedVoting {
        migrateNftVaultContract = true;
    }

    function disableAutoUserSettings() external {
        require(msg.sender == deployer, "deployer only!");
        canUpdateUserSettings = false;
    }

    function transferSettings(address _user, address _nftContract) public {
        require(msg.sender == deployer, "deployer only!");
        require(canUpdateUserSettings, "settings already updated");

        (address _defaultharvest, address _defaultHarvest2, uint256 _defaultMinHarvestOink, 
            uint256 _defaultminHarvestDegen, uint256 _fee) = INftVault(_nftContract).userSettings(_user);

        UserSettings storage userData = userSettings[_user];
        userData.fee = _fee;
        userData.defaultHarvest1 = _defaultharvest;
        userData.defaultHarvest2 = _defaultHarvest2;
        userData.minimumHarvest1 = _defaultMinHarvestOink;
        userData.minimumHarvest2 = _defaultminHarvestDegen;
    }

    function massUpdateSettings(address[] calldata _users, address _contract) external {
        for(uint256 i = 0; i< _users.length; ++i) {
            transferSettings(_users[i], _contract);
        }
    }
}
